  if (/\b(proof|verification|test|evidence|receipt)\b/.test(t)) return 'verification';
  if (/\b(vision|mission|intent)\b/.test(t)) return 'vision';
  if (/\b(how to|runbook|procedure|steps)\b/.test(t)) return 'procedure';
